import { createDataRouter, RouterApplication } from "@kasperrt/smolter/preact";
import { render } from "preact";
import * as rootModule from "./root";
import { routes } from "./routes";

const router = createDataRouter(routes, { browser: true });
const container = document.getElementById("root")!;

render(
  <RouterApplication router={router} routes={routes} root={undefined} rootModule={rootModule} />,
  container,
);
